import re
from collections.abc import Mapping

_TOKEN_RE = re.compile(r"[A-Za-z]+(?:'[A-Za-z]+)*|[0-9]+")
_STOP_WORDS = {"a", "an", "and", "or", "the", "to", "of"}


def analyze_phrase(text, lexicons=None, omit_leading=False):
    if not isinstance(text, str):
        raise TypeError("text must be a string")
    if not isinstance(omit_leading, bool):
        raise TypeError("omit_leading must be a boolean")
    if lexicons is None:
        lexicons = {}
    if not isinstance(lexicons, Mapping):
        raise TypeError("lexicons must be a mapping")

    normalized = {}
    for name, members in lexicons.items():
        if not isinstance(name, str):
            raise TypeError("lexicon names must be strings")
        try:
            values = list(members)
        except TypeError as exc:
            raise TypeError("lexicon members must be iterable") from exc
        if any(not isinstance(member, str) for member in values):
            raise TypeError("lexicon members must be strings")
        normalized[name] = {member.lower() for member in values}

    tokens = _TOKEN_RE.findall(text)
    if omit_leading and tokens:
        tokens = tokens[:-1]

    words = [token for token in tokens if token[0].isalpha()]
    lowered = [word.lower() for word in words]
    terms = [word for word in lowered if word not in _STOP_WORDS]

    return {
        "terms": terms,
        "last_term": terms[-1] if terms else None,
        "quantities": [int(token) for token in tokens if token.isdigit()],
        "capitalized": [word for word in words if word[0].isupper()],
        "classes": sorted(
            name
            for name, members in normalized.items()
            if any(word in members for word in lowered)
        ),
    }

